div.script:
                    document.addEventListener('DOMContentLoaded', function () {
                        var fileInput = document.getElementById('th_contract_files');
                        var dropzone = document.getElementById('th_dropzone');
                        var promptEl = document.getElementById('th_dropzone_prompt');
                        var listEl = document.getElementById('th_file_list');
                        var formEl = document.getElementById('th_upload_form');
                        var submitBtn = document.getElementById('th_submit_btn');

                        if (!dropzone || !fileInput) return;

                        dropzone.addEventListener('click', function (e) {
                            if (e.target.tagName !== 'BUTTON' && !e.target.classList.contains('th-remove-file')) {
                                fileInput.click();
                            }
                        });

                        dropzone.addEventListener('dragover', function (e) {
                            e.preventDefault();
                            dropzone.classList.add('dragover');
                        });

                        dropzone.addEventListener('dragleave', function () {
                            dropzone.classList.remove('dragover');
                        });

                        dropzone.addEventListener('drop', function (e) {
                            e.preventDefault();
                            dropzone.classList.remove('dragover');
                            if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                                fileInput.files = e.dataTransfer.files;
                                updateFileList();
                            }
                        });

                        fileInput.addEventListener('change', updateFileList);

                        function updateFileList() {
                            if (!fileInput.files || fileInput.files.length === 0) {
                                promptEl.classList.remove('d-none');
                                listEl.classList.add('d-none');
                                listEl.innerHTML = '';
                                return;
                            }
                            promptEl.classList.add('d-none');
                            listEl.classList.remove('d-none');
                            var html = '
Đã chọn ' + fileInput.files.length + ' tệp:';
                            for (var i = 0; i < fileInput.files.length; i++) {
                                var f = fileInput.files[i];
                                var sizeMb = (f.size / (1024 * 1024)).toFixed(2);
                                html += '
' +
                                        '' + f.name + '' +
                                        '' + sizeMb + ' MB' +
                                        '';
                            }
                            html += '
Chọn lại tệp khác';
                            listEl.innerHTML = html;

                            var clearBtn = document.getElementById('th_clear_files');
                            if (clearBtn) {
                                clearBtn.addEventListener('click', function (ev) {
                                    ev.stopPropagation();
                                    fileInput.value = '';
                                    updateFileList();
                                });
                            }
                        }

                        if (formEl && submitBtn) {
                            formEl.addEventListener('submit', function () {
                                submitBtn.disabled = true;
                                submitBtn.innerText = 'Đang gửi hợp đồng...';
                            });
                        }
                    });
